public class CauseChainWalkerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object rootMessage(Throwable error) {
        try {
            Throwable root = CauseChainWalker.rootCause(error);
            return root == null ? "<null>" : root.getMessage();
        } catch (Throwable crash) {
            return "rootCause threw " + crash.getClass().getSimpleName();
        }
    }

    static Object names(Throwable error) {
        try {
            return CauseChainWalker.chainNames(error);
        } catch (Throwable crash) {
            return "chainNames threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        Throwable deep = new NumberFormatException("root");
        Throwable middle = new IllegalStateException("middle", deep);
        Throwable top = new RuntimeException("top", middle);
        Throwable lone = new java.io.IOException("solo");

        check("rootCause of a three-link chain", "root", rootMessage(top));
        check("rootCause of an exception with no cause", "solo", rootMessage(lone));
        check("chainNames of a three-link chain",
                "RuntimeException -> IllegalStateException -> NumberFormatException", names(top));
        check("chainNames of an exception with no cause", "IOException", names(lone));

        SelfCausedFault selfCaused = new SelfCausedFault("loop");
        check("rootCause survives a self-caused exception", "loop", rootMessage(selfCaused));
        check("chainNames survives a self-caused exception", "SelfCausedFault", names(selfCaused));

        OuterLoopFault outer = new OuterLoopFault("outer");
        InnerLoopFault inner = new InnerLoopFault("inner");
        outer.link = inner;
        inner.link = outer;
        check("rootCause survives a two-link loop", "inner", rootMessage(outer));
        check("chainNames survives a two-link loop", "OuterLoopFault -> InnerLoopFault", names(outer));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

class SelfCausedFault extends RuntimeException {
    SelfCausedFault(String message) {
        super(message);
    }

    @Override
    public synchronized Throwable getCause() {
        return this;
    }
}

class OuterLoopFault extends RuntimeException {
    Throwable link;

    OuterLoopFault(String message) {
        super(message);
    }

    @Override
    public synchronized Throwable getCause() {
        return link;
    }
}

class InnerLoopFault extends RuntimeException {
    Throwable link;

    InnerLoopFault(String message) {
        super(message);
    }

    @Override
    public synchronized Throwable getCause() {
        return link;
    }
}

