/**
 * TASK: Follow an exception's chain of causes.
 *
 * rootCause(error) returns the deepest exception in the chain -- the last one
 * reachable through getCause(). An exception with no cause is its own root.
 *
 * chainNames(error) returns the simple class name of every exception from the
 * outermost inwards, joined with " -> ".
 *
 * Example: new RuntimeException("top", new java.io.IOException("io"))
 *   rootCause(...)  -> the IOException
 *   chainNames(...) -> "RuntimeException -> IOException"
 *
 * Careful: a badly built chain can name itself as its own cause, or two
 * exceptions can point at each other. Remember which exceptions you have
 * already visited and stop when one repeats, so neither method ever hangs.
 */
import java.util.ArrayList;
import java.util.List;

public class CauseChainWalker {

    public static Throwable rootCause(Throwable error) {
        if (error == null) {
            return null;
        }
        List<Throwable> seen = new ArrayList<>();
        Throwable current = error;
        while (true) {
            seen.add(current);
            Throwable next = current.getCause();
            if (next == null || alreadySeen(seen, next)) {
                return current;
            }
            current = next;
        }
    }

    public static String chainNames(Throwable error) {
        List<Throwable> seen = new ArrayList<>();
        StringBuilder names = new StringBuilder();
        Throwable current = error;
        while (current != null && !alreadySeen(seen, current)) {
            seen.add(current);
            if (names.length() > 0) {
                names.append(" -> ");
            }
            names.append(current.getClass().getSimpleName());
            current = current.getCause();
        }
        return names.toString();
    }

    private static boolean alreadySeen(List<Throwable> seen, Throwable candidate) {
        for (Throwable earlier : seen) {
            if (earlier == candidate) {
                return true;
            }
        }
        return false;
    }
}
